using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var build = BinaryLog.ReadBuild(binlogPath);

        // List all projects
        Console.WriteLine("=== PROJECTS IN BUILD ===");
        build.VisitAllChildren<Project>(p =>
        {
            Console.WriteLine($"  {p.Name} -> Succeeded={p.Succeeded}");
        });
        Console.WriteLine();

        // Show project dependency info
        Console.WriteLine("=== PROJECT REFERENCES (from items) ===");
        build.VisitAllChildren<NamedNode>(node =>
        {
            if (node.Name == "ProjectReference" && node is Folder f)
            {
                var parent = node.Parent;
                string projectName = "";
                while (parent != null)
                {
                    if (parent is Project p) { projectName = p.Name; break; }
                    parent = parent.Parent;
                }
                Console.WriteLine($"  {projectName} references:");
                foreach (var child in f.Children)
                    Console.WriteLine($"    -> {child}");
            }
        });
        Console.WriteLine();

        // Show all items to find NuGet references
        Console.WriteLine("=== NUGET PACKAGE REFERENCES ===");
        build.VisitAllChildren<NamedNode>(node =>
        {
            if (node.Name == "PackageReference" && node is Folder f)
            {
                var parent = node.Parent;
                string projectName = "";
                while (parent != null)
                {
                    if (parent is Project p) { projectName = p.Name; break; }
                    parent = parent.Parent;
                }
                Console.WriteLine($"  {projectName} packages:");
                foreach (var child in f.Children)
                    Console.WriteLine($"    -> {child}");
            }
        });
        Console.WriteLine();

        // Try to find source file contents or targets
        Console.WriteLine("=== FAILED TARGETS ===");
        build.VisitAllChildren<Target>(t =>
        {
            if (!t.Succeeded)
                Console.WriteLine($"  {t.Name} in {t.Project?.Name}");
        });
    }
}
