    {
        var binlogPath = args[0];
        var build = BinaryLog.ReadBuild(binlogPath);

        // Find PackageReference items
        Console.WriteLine("=== PACKAGE REFERENCES ===");
        build.VisitAllChildren<AddItem>(ai =>
        {
            if (ai.Name == "PackageReference")
            {
                var proj = ai.Parent;
                string projectName = "";
                while (proj != null)
                {
                    if (proj is Project p) { projectName = p.Name; break; }
                    proj = proj.Parent;
                }
                Console.WriteLine($"  [{projectName}]:");
                foreach (var child in ai.Children)
                    Console.WriteLine($"    {child}");
            }
        });

        // Look at SourceFilesProjectOutputGroupOutput or Compile items
        Console.WriteLine("\n=== COMPILE ITEMS (source files) ===");
        build.VisitAllChildren<AddItem>(ai =>
        {
            if (ai.Name == "Compile")
            {
                var proj = ai.Parent;
                string projectName = "";
                while (proj != null)
                {
                    if (proj is Project p) { projectName = p.Name; break; }
                    proj = proj.Parent;
                }
                foreach (var child in ai.Children)
                    Console.WriteLine($"  [{projectName}] {child}");
            }
        });

        // Get properties for each project to understand TFM
        Console.WriteLine("\n=== TARGET FRAMEWORK ===");
        build.VisitAllChildren<Property>(prop =>
        {
            if (prop.Name == "TargetFramework")
            {
                var proj = prop.Parent;
                string projectName = "";
                while (proj != null)
                {
                    if (proj is Project p) { projectName = p.Name; break; }
                    proj = proj.Parent;
                }
                if (projectName != "")
                    Console.WriteLine($"  [{projectName}] {prop.Name} = {prop.Value}");
            }
        });

        // Look for NuGet restore messages
        Console.WriteLine("\n=== NUGET RESTORE MESSAGES ===");
        build.VisitAllChildren<Message>(msg =>
        {
            if (msg.Text != null && (msg.Text.Contains("Newtonsoft") || msg.Text.Contains("PackageReference") || msg.Text.Contains("NU")))
            {
                Console.WriteLine($"  {msg.Text.Substring(0, Math.Min(msg.Text.Length, 200))}");
            }
        });
    }
}
